<div class="profile-head"><div><span class="panel-overline">NIK <?= h($row['nik']?:'—') ?> · TAHUN BUKU <?= h($row['fiscal_year']) ?></span><h2><?= h($row['cooperative_name']) ?></h2><p>RAT <?= $row['rat_date']?h(date('d M Y',strtotime($row['rat_date']))):'belum dicatat' ?> · laporan <?= h($statuses[$row['verification_status']]??$row['verification_status']) ?></p></div><span class="pill <?= $row['verification_status']==='verified'?'pill-green':($row['verification_status']==='submitted'?'pill-blue':'pill-muted') ?>"><?= h($statuses[$row['verification_status']]??$row['verification_status']) ?></span></div>
