<section class="panel detail-panel"><span class="panel-overline">DOKUMEN PENDUKUNG</span><?php foreach ($documents as $doc): ?><div class="evidence-row"><a class="row-link" href="<?= site_url('admin/laporan-tahunan/'.$row['id'].'/dokumen/'.$doc['id']) ?>"><?= h($doc['original_name']) ?> ↓</a><span><?= h($doc['type_name']?:'Dokumen') ?></span><small><?= h(date('d M Y H:i',strtotime($doc['uploaded_at']))) ?></small></div><?php endforeach; ?><?php if (!$documents): ?><p class="case-description">Belum ada dokumen. Unggah RAT atau laporan keuangan sebelum dikirim.</p><?php endif; ?><?php if ($can_edit): ?><form class="upload-inline" method="post" enctype="multipart/form-data" action="<?= site_url('admin/laporan-tahunan/'.$row['id'].'/dokumen') ?>"><?= csrf_input() ?><label>Jenis dokumen<select name="document_type_item_id" required><option value="">Pilih</option><?php foreach ($types as $type): ?><option value="<?= $type['id'] ?>"><?= h($type['name']) ?></option><?php endforeach; ?></select></label><label>PDF/foto, maksimal 10 MB<input type="file" name="document" accept="application/pdf,image/jpeg,image/png,image/webp" required></label><button class="button button-dark button-small">Unggah dokumen</button></form><?php endif; ?></section>
<?php if ($can_edit): ?><section class="panel detail-panel"><span class="panel-overline">KIRIM UNTUK VERIFIKASI</span><p>Periksa seluruh angka dan dokumen. Setelah dikirim, isian terkunci sampai petugas mengembalikan untuk perbaikan.</p><form method="post" action="<?= site_url('admin/laporan-tahunan/'.$row['id'].'/kirim') ?>" onsubmit="return confirm('Kirim laporan dan kunci isian?')"><?= csrf_input() ?><button class="button button-dark">Kirim laporan →</button></form></section><?php endif; ?>
<?php if ($can_verify): ?><section class="form-panel case-followup"><div class="form-intro"><span class="panel-overline">VERIFIKASI PETUGAS</span><h2>Periksa kesesuaian dokumen</h2></div><form method="post" action="<?= site_url('admin/laporan-tahunan/'.$row['id'].'/verifikasi') ?>"><?= csrf_input() ?><div class="form-grid"><label>Keputusan<select name="decision"><option value="returned">Kembalikan untuk perbaikan</option><option value="verified">Verifikasi data</option></select></label><label class="form-full">Catatan pemeriksa <span class="required">*</span><textarea name="review_note" rows="3" minlength="10" maxlength="5000" required></textarea></label></div><div class="form-actions"><button class="button button-dark">Simpan keputusan →</button></div></form></section><?php endif; ?>
